-- Table: budget_revision
-- Source: accounting_admin_db.sql (2. Accounting core and budget)
--
-- One migration per table. Do not edit this file after it has been applied;
-- add a new migration for later schema changes.

CREATE TABLE IF NOT EXISTS budget_revision (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    revision_number  VARCHAR(50) NOT NULL UNIQUE,
    budget_plan_id   BIGINT NOT NULL REFERENCES budget_plan(id),
    revision_date    DATE NOT NULL,
    requested_by     BIGINT REFERENCES masterdata_user(id),
    current_amount   NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (current_amount >= 0),
    requested_amount NUMERIC(18,2) NOT NULL DEFAULT 0 CHECK (requested_amount >= 0),
    difference       NUMERIC(18,2) NOT NULL DEFAULT 0,
    reason           TEXT,
    status           VARCHAR(20) NOT NULL DEFAULT 'pending'
                     CHECK (status IN ('draft', 'created', 'approved', 'rejected', 'pending', 'completed', 'reopen')),
    approved_by      BIGINT REFERENCES masterdata_user(id),
    approved_at      TIMESTAMPTZ,
    notes            TEXT,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
